class Solution:
    def maxAncestorDiff(self, root) -> int:
        def dfs(node, lo, hi):
            if not node:
                return hi - lo
            lo = min(lo, node.val)
            hi = max(hi, node.val)
            return max(dfs(node.left, lo, hi), dfs(node.right, lo, hi))
        return dfs(root, root.val, root.val)

